export function createSceneLayers(THREE,scene){
  const $=id=>document.getElementById(id),group=new THREE.Group();group.name='decorative-environment';scene.add(group);
  const fresnel=new THREE.Mesh(new THREE.SphereGeometry(1,40,24),new THREE.MeshBasicMaterial({color:0x80d8e2,wireframe:true,transparent:true,opacity:.16,depthWrite:false}));fresnel.visible=false;scene.add(fresnel);const link=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(),new THREE.Vector3()]),new THREE.LineDashedMaterial({color:0x92e3ee,dashSize:.4,gapSize:.2,transparent:true,opacity:.6}));scene.add(link);link.visible=false;
  function clear(){group.traverse(o=>{o.geometry?.dispose();if(o.material)for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose();});group.clear();}
  function box(w,h,d,x,y,z,opacity=.12){const g=new THREE.BoxGeometry(w,h,d),edges=new THREE.LineSegments(new THREE.EdgesGeometry(g),new THREE.LineBasicMaterial({color:0x7290a8,transparent:true,opacity:.35,depthWrite:false}));edges.position.set(x,y,z);group.add(edges);if(opacity){const m=new THREE.Mesh(g,new THREE.MeshBasicMaterial({color:0x8b9aab,transparent:true,opacity,depthWrite:false,side:THREE.DoubleSide}));m.position.copy(edges.position);group.add(m);}else g.dispose();}
  function environment(){clear();group.visible=$('environment').checked;if(!group.visible)return;const values=['roomwidth','roomdepth','roomheight'].map(id=>Math.max(2,Math.min(150,+$(id).value||2)));values.forEach((v,i)=>$( ['roomwidth','roomdepth','roomheight'][i]).value=v);const [w,d,h]=values;box(w,h,d,w/2,h/2,-d/2,0);for(let x=0;x<=w;x+=w/5){const geo=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(x,h,-d),new THREE.Vector3(x,h,0),new THREE.Vector3(Math.min(w,x+w/10),h+.8,-d/2),new THREE.Vector3(x,h,-d)]);group.add(new THREE.Line(geo,new THREE.LineBasicMaterial({color:0x8ba4b6,transparent:true,opacity:.22,depthWrite:false})));}for(let x=w*.2;x<w;x+=w*.3){box(Math.min(1.5,w*.07),h*.6,d*.45,x,h*.3,-d*.55,.035);}box(w,.16,d*.2,w/2,h*.5,-d*.12,.025);}
  function update(sample,frequency,radiusFn){const show=$('fresnel').checked&&!!sample;fresnel.visible=link.visible=show;if(!show)return;const a=new THREE.Vector3(0,+$('beaconalt').value,0),b=new THREE.Vector3(sample.x,sample.z,-sample.y),delta=b.clone().sub(a),distance=delta.length(),radius=radiusFn(distance,frequency);if(distance<.001){fresnel.visible=link.visible=false;$('fresnelinfo').textContent='Sample coincides with the beacon.';return;}fresnel.position.copy(a).add(b).multiplyScalar(.5);fresnel.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),delta.clone().normalize());fresnel.scale.set(radius,distance/2,radius);const attr=link.geometry.attributes.position;attr.setXYZ(0,a.x,a.y,a.z);attr.setXYZ(1,b.x,b.y,b.z);attr.needsUpdate=true;link.geometry.computeBoundingSphere();link.computeLineDistances();$('fresnelinfo').textContent=`Link ${distance.toFixed(2)} m · max first-zone radius ${radius.toFixed(2)} m · ${frequency} MHz`;
  }
  $('environment').onchange=environment;for(const id of ['roomwidth','roomdepth','roomheight'])$(id).onchange=environment;return {update,environment,fresnel,group};
}
